/**
 * Generates the synthetic sample statement the app's "Try with sample data"
 * button loads.
 *
 *   npm run sample
 *
 * Everything in it is invented: the bank ("Demo Bank"), the account holder,
 * every merchant, every person, every UPI handle (the providers `@okdemo`,
 * `@demoupi` and `@demopay` do not exist) and every reference number. The
 * account number is a masked placeholder. No real statement was used to make
 * it; the narration layouts are the synthetic styles in src/core/narration.
 *
 * The output is fully determined by SEED, so the committed file can be
 * regenerated byte for byte (tests/sample.test.ts checks this).
 *
 * A few things are planted on purpose so the signals have something to find:
 * monthly payments (rent, two subscriptions, broadband, electricity, a 28-day
 * mobile recharge), one payment charged twice on the same day, one very large
 * restaurant bill, and one month with a hospital bill.
 */

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const SEED = 20260401;
const MASKED_ACCOUNT = 'XXXXXXXX0000';
const MONTHS = [
  { year: 2026, month: 4, name: 'Apr', days: 30 },
  { year: 2026, month: 5, name: 'May', days: 31 },
  { year: 2026, month: 6, name: 'Jun', days: 30 },
  { year: 2026, month: 7, name: 'Jul', days: 31 },
  { year: 2026, month: 8, name: 'Aug', days: 31 },
  { year: 2026, month: 9, name: 'Sep', days: 30 },
];

/** Small seeded generator (mulberry32), so the sample never changes by accident. */
function createRandom(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function pad(value, width = 2) {
  return String(value).padStart(width, '0');
}

/** Rupees with Indian digit grouping and two decimals: 123456.5 -> 1,23,456.50 */
function inr(paise) {
  const rupees = String(Math.floor(paise / 100));
  const fraction = pad(paise % 100);
  const grouped =
    rupees.length <= 3
      ? rupees
      : `${rupees.slice(0, -3).replace(/\B(?=(\d{2})+(?!\d))/g, ',')},${rupees.slice(-3)}`;
  return `${grouped}.${fraction}`;
}

function csvCell(value) {
  return /[",\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

export function generateSample(seed = SEED) {
  const random = createRandom(seed);
  const between = (low, high) => low + Math.floor(random() * (high - low + 1));
  const pick = (items) => items[Math.floor(random() * items.length)];
  const chance = (probability) => random() < probability;

  let referenceCounter = 0;
  /** A unique twelve-digit reference. */
  const ref = () => {
    referenceCounter += between(1, 97);
    return String(410000000000 + referenceCounter * 1009);
  };
  let neftCounter = 0;
  const neftRef = () => {
    neftCounter += 1;
    return `DEMON26${pad(neftCounter, 6)}`;
  };

  /** @type {{ year: number, month: number, day: number, order: number, narration: string, debit: number, credit: number }[]} */
  const entries = [];
  let order = 0;
  const add = (m, day, narration, rupees, isCredit = false) => {
    const paise = Math.round(rupees * 100);
    entries.push({
      year: m.year,
      month: m.month,
      day: Math.min(Math.max(day, 1), m.days),
      order: (order += 1),
      narration,
      debit: isCredit ? 0 : paise,
      credit: isCredit ? paise : 0,
    });
  };

  // Narration builders, one per synthetic style.
  const styleA = (name, handle, note) =>
    `UPI-${name}-${handle}-DEMO000${between(1000, 9999)}-${ref()}${note ? `-${note}` : ''}`;
  const styleB = (name, handle, note, credit = false) =>
    `UPI/${credit ? 'CR' : 'DR'}/${ref()}/${name}/DEMO/${handle}${note ? `/${note}` : ''}`;
  const styleC = (name, handle, note) =>
    `TO TRANSFER-UPI/DR/${ref()}/${name}/DEMO/${handle}/${note}--`;
  const styleD = (kind, name, note) => `UPI/${kind}/${ref()}/${name}/${note}/DEMO BANK`;
  const styleE = (name, handle, note) =>
    `UPI/${name}/${handle}/${note}/DEMO BANK/${ref()}/DMO${between(100000, 999999)}`;
  const styleF = (handle, note) => `UPI/${ref()}/${note}/${handle}/DEMO BANK`;
  const styleG = (handle, code) => `UPIOUT/${ref()}/${handle}/${code}`;

  let rechargeDay = 6; // day of year offset for the 28-day mobile recharge
  const dayOfYearStart = MONTHS.map((_, index) =>
    MONTHS.slice(0, index).reduce((total, month) => total + month.days, 0),
  );

  MONTHS.forEach((m, index) => {
    const yy = String(m.year).slice(2);
    const posDate = (day) => `${pad(day)}${pad(m.month)}${yy}`;

    // Money in: salary on the 28th.
    add(
      m,
      28,
      `NEFT-${neftRef()}-ORBIT TECHNOLOGIES PAYROLL-SALARY ${m.name.toUpperCase()}`,
      62000,
      true,
    );

    // Fixed monthly outgoings.
    add(m, 3, styleD('P2A', 'VIKRAM PLACEHOLDER', `Rent ${m.name}`), 18500);
    add(m, 5, styleE('NIMBUS STREAM', 'nimbus.stream@demopay', 'Monthly plan'), 499);
    add(m, 12, styleA('TUNEWAVE MUSIC', 'tunewave@demoupi', 'SUBSCRIPTION'), 119);
    add(m, 15, styleB('FIBERNEST BROADBAND', 'fibernest@okdemo', 'Bill'), 799);
    add(
      m,
      between(9, 11),
      `ACH D- BRIGHTPOWER ELECTRICITY-DEMO778${between(1000, 9999)}`,
      between(1540, 1680),
    );

    // Mobile recharge every 28 days, whichever month that lands in.
    while (rechargeDay < dayOfYearStart[index] + m.days) {
      const day = rechargeDay - dayOfYearStart[index] + 1;
      if (day >= 1)
        add(m, day, styleA('SKYLINK MOBILE RECHARGE', 'skylink@demoupi', 'RECHARGE'), 299);
      rechargeDay += 28;
    }

    // Insurance, quarterly: it must not be mistaken for a monthly payment.
    if (m.month === 5 || m.month === 8) {
      add(m, 20, `NACH-DR-SURECOVER INSURANCE-000${between(10000, 99999)}`, 3200);
    }

    // Groceries: a weekly shop, a few top-ups, and milk every few days.
    for (const day of [4, 11, 18, 25]) {
      add(
        m,
        day + between(0, 2),
        styleA('GREENLEAF GROCERS', 'greenleaf.grocers@okdemo', 'GROCERIES'),
        between(640, 1780),
      );
    }
    for (let count = between(1, 3); count > 0; count -= 1) {
      add(m, between(1, m.days), styleG('freshbasket@demoupi', '5411'), between(180, 690));
    }
    for (let day = between(1, 4); day <= m.days; day += between(3, 5)) {
      add(m, day, styleA('A-ONE DAIRY', 'aonedairy@demoupi', 'MILK'), pick([58, 62, 64, 116]));
    }

    // Food: tea most days, a restaurant now and then, a late biryani.
    for (let day = between(1, 3); day <= m.days; day += between(2, 4)) {
      add(
        m,
        day,
        styleB('CHAI CORNER CAFE', 'chaicorner@okdemo', pick(['Tea', 'Snacks', 'Tea'])),
        pick([20, 30, 40, 60, 85, 140]),
      );
    }
    for (let count = between(2, 4); count > 0; count -= 1) {
      add(
        m,
        between(1, m.days),
        styleD('P2M', 'SPICE ROUTE KITCHEN', pick(['Dinner', 'Lunch'])),
        between(380, 1240),
      );
    }
    for (let count = between(1, 2); count > 0; count -= 1) {
      add(
        m,
        between(1, m.days),
        styleF('midnight.biryani@okdemo', 'Payment from app'),
        between(240, 460),
      );
    }

    // Transport: cabs, metro card top-ups, fuel.
    for (let count = between(4, 7); count > 0; count -= 1) {
      add(m, between(1, m.days), styleD('P2M', 'ZIPCAB RIDES', 'Ride fare'), between(95, 460));
    }
    add(m, between(2, 6), styleC('METRO RAIL RECHARGE', 'metrorail@demoupi', 'Card topup'), 500);
    add(m, between(16, 21), styleC('METRO RAIL RECHARGE', 'metrorail@demoupi', 'Card topup'), 500);
    const fuelDay = between(7, 24);
    add(m, fuelDay, `POS/CITYFUEL PETROL PUMP/DEMO CITY/${posDate(fuelDay)}`, between(1500, 2400));

    // Shopping. Urban Threads and Kartwheel match no default rule on purpose,
    // so the sample shows what "Other" looks like and how an override fixes it.
    if (chance(0.75)) {
      const day = between(1, m.days);
      add(m, day, `POS/URBAN THREADS/DEMO CITY/${posDate(day)}`, between(1250, 4400));
    }
    if (chance(0.6)) add(m, between(1, m.days), 'ECOM PUR/KARTWHEEL ONLINE', between(349, 2890));
    if (chance(0.5))
      add(m, between(1, m.days), `POS ${'X'.repeat(12)}0000 PAGETURN BOOKS`, between(299, 1150));

    // Health.
    for (let count = between(1, 2); count > 0; count -= 1) {
      add(
        m,
        between(1, m.days),
        `UPI ${ref()} PAID TO lakeside.pharmacy@okdemo`,
        between(160, 880),
      );
    }
    if (m.month === 6)
      add(m, 17, styleB('WELLSPRING CLINIC', 'wellspring@okdemo', 'Consultation'), 600);

    // People: money sent and money received.
    for (let count = between(1, 2); count > 0; count -= 1) {
      add(
        m,
        between(1, m.days),
        styleD('P2A', 'ASHA SAMPLE', pick(['Dinner split', 'Movie tickets', 'Gift share'])),
        between(350, 2600),
      );
    }
    if (chance(0.5)) {
      add(
        m,
        between(1, m.days),
        `IMPS-${ref()}-ROHAN PLACEHOLDER-DEMO BANK-Trip share`,
        between(1200, 4200),
      );
    }
    if (chance(0.7)) {
      add(
        m,
        between(1, m.days),
        styleB('MEERA TESTER', 'meera.tester@demopay', 'Paid back', true),
        between(300, 1900),
        true,
      );
    }

    // Cash.
    add(m, between(1, 14), 'ATM WDL DEMO NAGAR BRANCH', pick([2000, 3000, 5000]));
    if (chance(0.5))
      add(m, between(15, m.days), `ATW-${'X'.repeat(12)}0000-DEMO CITY`, pick([1000, 2000]));

    // Quarterly interest.
    if (m.month === 6) add(m, 30, 'INT PD 01-04-2026 TO 30-06-2026', 412, true);
    if (m.month === 9) add(m, 30, 'INT PD 01-07-2026 TO 30-09-2026', 447, true);
  });

  // Planted for the signals -------------------------------------------------
  const july = MONTHS[3];
  const august = MONTHS[4];
  // One purchase charged twice on the same day.
  add(july, 14, 'POS/URBAN THREADS/DEMO CITY/140726', 1849);
  add(july, 14, 'POS/URBAN THREADS/DEMO CITY/140726', 1849);
  // A refund a few days later, as money in.
  add(july, 19, 'ECOM PUR/KARTWHEEL ONLINE REFUND', 899, true);
  // One very large restaurant bill.
  add(august, 9, styleD('P2M', 'SPICE ROUTE KITCHEN', 'Family dinner'), 6400);
  // A hospital bill that makes August a heavy month for health.
  add(
    august,
    22,
    styleB('WELLSPRING HOSPITAL', 'wellspring.hospital@okdemo', 'Bill payment'),
    14500,
  );

  entries.sort(
    (a, b) => a.year - b.year || a.month - b.month || a.day - b.day || a.order - b.order,
  );

  const lines = [
    'Demo Bank - SAMPLE STATEMENT (synthetic data, not a real account)',
    'Account holder,SAMPLE HOLDER',
    `Account number,${MASKED_ACCOUNT}`,
    'Statement period,01/04/2026 to 30/09/2026',
    'Txn Date,Value Date,Narration,Chq./Ref.No.,Account No,Withdrawal Amt.,Deposit Amt.,Closing Balance',
  ];
  let balance = 84_200_00;
  for (const entry of entries) {
    balance += entry.credit - entry.debit;
    const date = `${pad(entry.day)}/${pad(entry.month)}/${entry.year}`;
    const reference = /(?<!\d)\d{12}(?!\d)/.exec(entry.narration)?.[0] ?? '';
    lines.push(
      [
        date,
        date,
        entry.narration,
        reference,
        MASKED_ACCOUNT,
        entry.debit ? inr(entry.debit) : '',
        entry.credit ? inr(entry.credit) : '',
        inr(balance),
      ]
        .map(csvCell)
        .join(','),
    );
  }
  lines.push('*** End of statement. This is synthetic sample data. ***');
  return `${lines.join('\n')}\n`;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const target = fileURLToPath(new URL('../src/sample/sample-statement.csv', import.meta.url));
  const csv = generateSample();
  writeFileSync(target, csv);
  console.log(`Wrote ${csv.trimEnd().split('\n').length - 6} synthetic transactions to ${target}`);
}
